package com.yumi.cafe.controller;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<Map<String,String>> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}@ExceptionHandler(ResponseStatusException.class)ResponseEntity<Map<String,String>> status(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(Map.of("error",e.getReason()==null?"Request failed":e.getReason()));}@ExceptionHandler(Exception.class)ResponseEntity<Map<String,String>> generic(Exception e){return ResponseEntity.status(500).body(Map.of("error","Unexpected server error"));}}
